head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.simulate = function(element, eventName) {
    var options = scwin.extend(defaultOptions, arguments[2] || {});
    var oEvent, eventType = null;
    for (var name in eventMatchers) {
        if (eventMatchers[name].test(eventName)) {
            eventType = name;
            break;
        }
    }
    if (!eventType)
        throw new TypeError('Only HTMLEvents and MouseEvents interfaces are supported');
    if (document.createEventObject) {
        options.clientX = options.pointerX;
        options.clientY = options.pointerY;
        var evt = document.createEventObject();
        oEvent = scwin.extend(evt, options);
        try {
            element.fireEvent('on' + eventName, oEvent);
        } catch (e) {
            if (element === window) {
                document.fireEvent('on' + eventName);
            }
        }
    } else if (document.createEvent) {
        oEvent = document.createEvent(eventType);
        if (eventType == 'HTMLEvents') {
            oEvent.initEvent(eventName, options.bubbles, options.cancelable);
        } else {
            oEvent.initMouseEvent(eventName, options.bubbles, options.cancelable, document.defaultView,
                options.button, options.pointerX, options.pointerY, options.pointerX, options.pointerY,
                options.ctrlKey, options.altKey, options.shiftKey, options.metaKey, options.button, element);
        }
        element.dispatchEvent(oEvent);
    } else {
        throw new TypeError('Not Supported');
    }
    return element;
}
scwin.tmpSetStatus = function(msg) {
    //windowContainer1.setWindowStatusMsg( msg );
    var tmp = windowContainer1.getWindow("local02");
    tmp.setWindowStatusMsg(msg);
}
scwin.getValue = function(id){
    var iframe = scwin.__getDom($p.id+"windowContainer1_subWindow0_iframe");
    var elmnt = ((id) => { const P = 'mf_', d = (k) => iframe.contentWindow.document.getElementById(k), dd = (k) => k.replace(/(mf_){2,}/g, P); let r = d(id); if (r) return r; let s = dd(P + id); r = d(s); if (r) return r; const g = s.indexOf('G_'); if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; } return d(s.replace(P, '')); })($p.id+id);
    return elmnt;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
}
scwin.addWindow = function() {
	if(windowContainer1.isExistWindow("daum")){
		alert(windowContainer1.getWindow("daum"));
		windowContainer1.selectNameLayer("windowContainer1_subWindow0");

		return;
	}else{
		windowContainer1.createWindow( "daum", "", "http://www.daum.net" , "","","selectWindow");	
	}
    sessionStorage.setItem("aa", "11");

    windowContainer1.createWindow( "<input type='button'>", "", "http://www.daum.net" , "","","selectWindow");

    scwin.__getDom($p.id+"windowContainer1").innerHTML="<div style='top:0px;left:0px;background-color:#ff000000;'>aa</div>";
    alert("123");
    scwin.__getDom($p.id+"windowContainer1").style.zIndex = "10000";
}
